public class InnerDataIntegrationFlowDataIntegrationFlowSourceFactory(Action<Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource> factoryAction = null) : SubResourceFactory<Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource>
{

    internal InnerDataIntegrationFlowDatasetSourceConfigurationFactory DatasetSourceFactory { get; set; }

    internal InnerDataIntegrationFlowS3SourceConfigurationFactory S3SourceFactory { get; set; }

    protected override Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource Create()
    {
        var dataIntegrationFlowSourceResult = CreateDataIntegrationFlowSource();
        factoryAction?.Invoke(dataIntegrationFlowSourceResult);

        return dataIntegrationFlowSourceResult;
    }

    private Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource CreateDataIntegrationFlowSource()
    {
        var dataIntegrationFlowSourceResult = new Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource();

        return dataIntegrationFlowSourceResult;
    }
    public override void CreateChildren(Humidifier.SCN.DataIntegrationFlowTypes.DataIntegrationFlowSource result)
    {
        base.CreateChildren(result);

        result.DatasetSource ??= DatasetSourceFactory?.Build();
        result.S3Source ??= S3SourceFactory?.Build();
    }

} // End Of Class

